const body = $input.first().json.body;
const services = ["web", "mobile", "enterprise", "ai", "automation", "integrations"];
const timelines = ["exploring", "urgent", "one-to-three", "three-plus"];
const fields = ["schemaVersion", "testOnly", "source", "requestId", "locale", "service", "timeline"];
const valid = body && typeof body === "object" && !Array.isArray(body)
  && Object.keys(body).length === fields.length
  && Object.keys(body).every((key) => fields.includes(key))
  && body.schemaVersion === 1 && body.testOnly === true && body.source === "genyx-test"
  && typeof body.requestId === "string" && /^genyx-test-[a-z0-9-]{1,48}$/.test(body.requestId)
  && ["es", "en"].includes(body.locale)
  && services.includes(body.service) && timelines.includes(body.timeline);
if (!valid) return [{ json: { statusCode: 400, ok: false, error: "invalid_test_payload" } }];
const priority = body.timeline === "urgent" ? "high" : body.timeline === "exploring" ? "low" : "normal";
return [{ json: { statusCode: 200, ok: true, testOnly: true, requestId: body.requestId, service: body.service, priority, stage: "new", persisted: false } }];
